#include "account_analysis_page.hpp"
#include <QtWidgets>
#include <limits>
namespace {
QString value(const QJsonValue& v){return v.isDouble()?QString::number(v.toDouble(),'g',15):v.isString()?v.toString():v.isBool()?v.toBool()?"是":"否":"未知";}
QTableWidget* table(QWidget* parent,QString name,QStringList labels){auto t=new QTableWidget(0,labels.size(),parent);t->setObjectName(name);t->setHorizontalHeaderLabels(labels);t->setEditTriggers(QAbstractItemView::NoEditTriggers);t->setSelectionBehavior(QAbstractItemView::SelectRows);t->horizontalHeader()->setSectionResizeMode(QHeaderView::ResizeToContents);t->horizontalHeader()->setStretchLastSection(true);return t;}
void fill(QTableWidget* t,const QJsonArray& rows,const QStringList& keys){t->setRowCount(0);for(auto v:rows){auto r=v.toObject();int row=t->rowCount();t->insertRow(row);for(int col=0;col<keys.size();col++){auto item=new QTableWidgetItem(value(r[keys[col]]));item->setData(Qt::UserRole,r);t->setItem(row,col,item);}}}
class HistoryPlot final:public QWidget {
public:QJsonArray rows;explicit HistoryPlot(QWidget* p):QWidget(p){setMinimumHeight(180);setObjectName("accountHistoryPlot");}
 void paintEvent(QPaintEvent*)override{QPainter p(this);p.fillRect(rect(),palette().color(QPalette::Base));p.setPen(palette().color(QPalette::Text));p.drawText(8,20,"原快照权益/现金曲线 · 横轴按原记录顺序；缺数断开，不是净收益率");if(rows.isEmpty()){p.drawText(8,60,"尚无此账户历史快照，未用当前行情补历史。");return;}double min=std::numeric_limits<double>::infinity(),max=-min;for(auto v:rows){auto r=v.toObject();if(!r["dateValid"].toBool())continue;for(auto key:{"totalAssets","cashBalance"})if(r[key].isDouble()){min=std::min(min,r[key].toDouble());max=std::max(max,r[key].toDouble());}}if(!std::isfinite(min))return;if(max==min)max=min+1;QRectF area(65,38,width()-85,height()-75);p.drawRect(area);p.drawText(5,45,QString::number(max,'g',9));p.drawText(5,height()-40,QString::number(min,'g',9));int series=0;for(auto key:{"totalAssets","cashBalance"}){p.setPen(QPen(series++==0?QColor("#477ac1"):QColor("#cb9045"),2));QPointF previous;bool last=false;for(int i=0;i<rows.size();i++){auto r=rows[i].toObject();if(!r["dateValid"].toBool()||!r[key].isDouble()){last=false;continue;}QPointF point(area.left()+area.width()*i/std::max(1,int(rows.size()-1)),area.bottom()-(r[key].toDouble()-min)/(max-min)*area.height());if(last)p.drawLine(previous,point);p.drawEllipse(point,2,2);previous=point;last=true;}}p.setPen(palette().color(QPalette::Text));p.drawText(65,height()-10,rows[0].toObject()["date"].toString()+" → "+rows.last().toObject()["date"].toString()+" · 蓝：总资产 / 橙：现金");}
};
}
AccountAnalysisPage::AccountAnalysisPage(std::shared_ptr<BusinessStore> s,bool isPaper,std::function<QJsonArray()> roster,QWidget* parent):QWidget(parent),store(std::move(s)),paper(isPaper),instruments(std::move(roster)){
 setObjectName("accountAnalysisPage");auto root=new QVBoxLayout(this);auto bar=new QHBoxLayout;accounts=new QComboBox(this);accounts->setObjectName("analysisAccount");bar->addWidget(accounts,1);auto refresh=new QPushButton("重读本机记录与现有报价",this);refresh->setObjectName("analysisReload");bar->addWidget(refresh);root->addLayout(bar);summary=new QLabel(this);summary->setWordWrap(true);summary->setObjectName("analysisSummary");root->addWidget(summary);
 auto tabs=new QTabWidget(this);root->addWidget(tabs,1);positions=table(tabs,"analysisPositions",{"完整身份","名称","股数","成本(元)","成本占比%","市值(元)","资产占比%","已实现(元)","浮盈(元)","累计盈亏(元)","行情日期"});tabs->addTab(positions,"结构 / 盈亏贡献");auto h=new QWidget(tabs);auto hl=new QVBoxLayout(h);plot=new HistoryPlot(h);hl->addWidget(plot);history=table(h,"analysisHistory",{"日期","总资产(元)","现金(元)","市值(元)","资产变化(元)","原累计盈亏(元)","算术一致"});hl->addWidget(history,1);original=new QPlainTextEdit(h);original->setObjectName("analysisOriginal");original->setReadOnly(true);hl->addWidget(original,1);tabs->addTab(h,"原快照权益 / 现金历史");flows=table(tabs,"analysisCashFlows",{"日期","完整身份","类型","记录现金流(元)","累计记录流(元)"});tabs->addTab(flows,"交易现金流（不是余额）");state=new QLabel(this);state->setObjectName("analysisState");state->setWordWrap(true);root->addWidget(state);
 connect(accounts,&QComboBox::currentIndexChanged,this,[this]{if(!filling)reload();});connect(refresh,&QPushButton::clicked,this,[this]{reload();});connect(history,&QTableWidget::cellClicked,this,[this](int row,int){if(row>=0&&history->item(row,0))original->setPlainText(QString::fromUtf8(QJsonDocument(history->item(row,0)->data(Qt::UserRole).toJsonObject()["original"].toObject()).toJson()));});reload();
}
void AccountAnalysisPage::setAccount(QString id){reload();int at=accounts->findData(id);if(at>=0){QSignalBlocker b(accounts);accounts->setCurrentIndex(at);reload();}}
void AccountAnalysisPage::reload(){try{QString keep=accounts->currentData().toString();filling=true;{QSignalBlocker b(accounts);accounts->clear();for(auto v:store->read("accounts")){const auto a=v.toObject();if((a["type"]=="paper")!=paper)continue;accounts->addItem(a["name"].toString(),a["id"].toString());}accounts->setCurrentIndex(std::max(0,accounts->findData(keep)));}active={};for(auto v:store->read("accounts"))if(v.toObject()["id"]==accounts->currentData().toString())active=v.toObject();if(active.isEmpty()){summary->clear();positions->setRowCount(0);history->setRowCount(0);flows->setRowCount(0);original->clear();static_cast<HistoryPlot*>(plot)->rows={};plot->update();filling=false;state->setText("此范围没有账户；前账户结果已清除。");return;}QJsonObject quotes;for(auto v:instruments?instruments():QJsonArray{}){const auto r=v.toObject();quotes[r["id"].toString()]=r["quote"];}auto out=accountAnalysis::evaluate(active,store->read("trades"),quotes,store->read("reports"));summary->setText("成本 "+value(out["cost"])+" · 市值 "+value(out["marketValue"])+" · 输入现金 "+value(out["cashBalance"])+" · 合计 "+value(out["totalAssets"])+" 元\n已实现 "+value(out["realized"])+" · 浮盈 "+value(out["unrealized"])+" · 累计盈亏 "+value(out["totalPnl"])+" · 记录净现金流 "+value(out["recordedCashFlow"])+" 元\n现金时点 "+active.value("cashAsOf").toString("未提供（可能是旧账户记录）"));fill(positions,out["positions"].toArray(),{"instrumentId","name","quantity","cost","costWeightPercent","marketValue","marketWeightPercent","realized","unrealized","totalPnl","quoteDate"});original->clear();fill(history,out["history"].toArray(),{"date","totalAssets","cashBalance","marketValue","assetChange","totalPnl","arithmeticConsistent"});fill(flows,out["cashPath"].toArray(),{"date","instrumentId","side","cashDelta","cumulativeRecordedFlow"});auto curve=static_cast<HistoryPlot*>(plot);curve->rows=out["history"].toArray();curve->update();filling=false;state->setText(out["boundary"].toString());}catch(const std::exception& e){filling=false;state->setText(QString::fromUtf8(e.what()));}}
